[
{"name":"SERVER: C*NT FESTA","aliases":["Server CNT Festa Santiago 2026","SERVER Halloween Night Teatro Roma"],"city":"santiago","date":"2026-11-01","start_date":"2026-11-01","end_date":"2026-11-02","description":"SERVER turns Teatro Roma into a queer Halloween mainframe: drag, perreo, K-pop, urban heat and cosplay collide in a one-night feed where the freakiest look gets the crown.","link":"https://www.passline.com/view-event/server-cnt-festa","ticket_url":"https://www.passline.com/view-event/server-cnt-festa","location":"Teatro Roma, San Diego 236, Santiago Centro, Santiago, Chile","lat":-33.4524,"lng":-70.6502,"vibe":"queer Halloween collision of perreo, K-pop, drag and full-contact cosplay","intel":{"hours":"22:00 Sunday 1 November–04:00 Monday 2 November 2026.","entry_wait":"Named-ticket sales are active; bring the matching identity document and leave time for the venue’s admission check.","best_arrival":"Come at 22:00 to see the costume field at full voltage before the dance floor compresses around the performances.","crowd_mix":"Queer Halloween dancers, drag audiences, K-pop and urban-music fans, cosplay diehards and Santiago friends who want a single-room spectacle.","dress_code":"Costume and cosplay are central to the night, with prizes for Best Costume and Cunt Cosplay; make your look mobile enough to dance in.","host_inclusivity":"The organiser explicitly describes a safe, inclusive and diverse space and bars discriminatory, violent or harassing conduct.","lineup":"Q_ARE, Rosimar and Big Blas; DJs Planta Carnívora and Alonso Montero; drag by Alexa Da'Kiwi and Bárbara Banks.","age_limit":"18+; government ID required at entry.","source_urls":["https://www.passline.com/view-event/server-cnt-festa","https://tuacceso.cl/teatroroma/"],"research_status":"official_ticketing_date_hours_venue_address_lineup_age_and_safe_space_policy_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Fiesta de Disfraces: Halloween Queer","aliases":["Halloween Queer Lima 2026","Fiesta de Disfraces La Casona Lima"],"city":"lima","date":"2026-10-31","start_date":"2026-10-31","end_date":"2026-11-01","description":"Lima’s queer Halloween gets its costume switch flipped at La Casona: a mixed floor for maximal looks, playful chaos and the particular thrill of becoming someone else under Miraflores lights.","link":"https://www.gayout.com/south-america/peru/lima/events/fiesta-de-disfraces-halloween-queer-2026-10-31","ticket_url":"https://www.gayout.com/south-america/peru/lima/events/fiesta-de-disfraces-halloween-queer-2026-10-31","location":"Discoteca La Casona, Avenida Petit Thouars 1234, Miraflores, Lima, Peru","lat":-12.1237,"lng":-77.0304,"vibe":"queer Halloween costume floor with Miraflores energy, mixed crowd and playful prize-night momentum","intel":{"hours":"21:00 Saturday 31 October 2026; confirm the final closing time with the organiser.","entry_wait":"The event is listed as 18+; use the live event page or the cited organiser channel for current entry and ticket terms.","best_arrival":"Arrive near 21:00 to take in the costume competition before the dance floor turns fully late-night.","crowd_mix":"Lima’s queer community, mixed LGBTQ+ groups, Halloween costume-makers and friends arriving for music, dancing and surprises.","dress_code":"Costume required in spirit: the published guidance calls for a disguise, with prizes for the most original looks.","host_inclusivity":"The listing explicitly invites celebration with Lima’s queer community and identifies a mixed LGBTQ+ crowd.","lineup":"Music, dancing, surprises and costume prizes are confirmed; no individual DJ lineup is published.","age_limit":"18+.","source_urls":["https://www.gayout.com/south-america/peru/lima/events/fiesta-de-disfraces-halloween-queer-2026-10-31"],"research_status":"verified_event_directory_date_time_full_address_queer_format_age_and_costume_guidance_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"RUSH: REWIND","aliases":["Rush Rewind Johannesburg 2026","RUSH Rewind Level Three"],"city":"johannesburg","date":"2026-10-03","start_date":"2026-10-03","end_date":"2026-10-04","description":"RUSH: REWIND asks Johannesburg to dance before the algorithm got there: a queer-led throwback universe built for rooftop arrival, themed looks and the kind of floor where memory is a weapon.","link":"https://www.rushclub.co.za/","ticket_url":"https://www.rushclub.co.za/","location":"Level Three, Kramerville Place, 14A Kramer Road, Kramerville, Sandton, Gauteng 2090, South Africa","lat":-26.1057,"lng":28.0673,"vibe":"queer-led Johannesburg throwback universe with rooftop arrival and full dance-floor release","intel":{"hours":"18:00 Saturday 3 October 2026; confirm the final closing time in the active Rush ticket flow.","entry_wait":"Entry tiers begin at R100 and guest-list access remains capacity-dependent; lock in a ticket rather than treating the list as guaranteed access.","best_arrival":"Use the 18:00 start for the rooftop social window before the party settles into its later dance-floor peak.","crowd_mix":"Johannesburg LGBTQ+ regulars, allies, themed-party devotees and people looking for an explicitly queer-led alternative to a generic club night.","dress_code":"No fixed outfit rule is published, but RUSH builds each event around a distinct visual world—come ready to inhabit the rewind theme.","host_inclusivity":"Rush describes itself as queer-led and everyone-respecting; its published rules prohibit discrimination, harassment and intimidating deliberate misgendering.","lineup":"Live DJ and performance detail is released through Rush’s active event channels.","age_limit":"18+; valid government photo ID may be required.","source_urls":["https://www.rushclub.co.za/","https://www.mambaonline.com/2026/07/17/rush-is-here-johannesburg-gets-a-bold-new-queer-party-experience/"],"research_status":"official_date_start_time_venue_brand_and_queer_host_policy_verified_final_line